package com.tanerinal.education.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.tanerinal.education.domain.Product;import com.tanerinal.education.mapper.*;import com.tanerinal.education.web.dto.*;import java.time.Duration;import java.util.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;@Service public class ProductCatalogService{public static final String CACHE_KEY="education:catalog:products:v1";private final ProductMapper products;private final ReviewMapper reviews;private final StringRedisTemplate redis;private final ObjectMapper mapper;public ProductCatalogService(ProductMapper products,ReviewMapper reviews,StringRedisTemplate redis,ObjectMapper mapper){this.products=products;this.reviews=reviews;this.redis=redis;this.mapper=mapper;}public List<ProductResponse> list(){try{String cached=redis.opsForValue().get(CACHE_KEY);if(cached!=null)return mapper.readValue(cached,new TypeReference<>(){});}catch(Exception ignored){}List<ProductResponse> result=products.selectList(new LambdaQueryWrapper<Product>().orderByAsc(Product::getId)).stream().map(product->ProductResponse.from(product,reviews.average(product.getId()),reviews.count(product.getId()),reviews.reviews(product.getId()).stream().map(ProductReviewResponse::from).toList())).toList();try{redis.opsForValue().set(CACHE_KEY,mapper.writeValueAsString(result),Duration.ofMinutes(5));}catch(Exception ignored){}return result;}public void invalidate(){try{redis.delete(CACHE_KEY);}catch(Exception ignored){}}}
